import {MURAL_LEFT,MURAL_RIGHT} from './core.mjs';
let serial=0;
const repeat=(n,fn)=>Array.from({length:n},(_,i)=>fn(i)).join('');
export function icon(name,cls=''){
 const paths={tablet:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M9 18h6"/>',bag:'<path d="M5 8h14l2 13H3L5 8Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',map:'<path d="m2 5 6-3 8 3 6-3v17l-6 3-8-3-6 3V5Z"/><path d="M8 2v17M16 5v17"/>',gear:'<path d="m9 3 1-2h4l1 2 3 2 2 .2 2 3-1 2v4l1 2-2 3-2 .2-3 2-1 2h-4l-1-2-3-2-2-.2-2-3 1-2v-4l-1-2 2-3 2-.2Z"/><circle cx="12" cy="12" r="4"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',arrow:'<path d="M3 12h18m-7-7 7 7-7 7"/>',back:'<path d="M21 12H3m7-7-7 7 7 7"/>',check:'<path d="m5 12 5 5 10-11"/>',lens:'<circle cx="10" cy="10" r="7"/><path d="m15 15 7 7"/>',rotate:'<path d="M20 8a8 8 0 1 0 0 8M20 2v6h-6"/>',sound:'<path d="M3 9h4l5-5v16l-5-5H3V9Zm13-2a7 7 0 0 1 0 10m3-13a11 11 0 0 1 0 16"/>',note:'<path d="M5 2h10l4 4v16H5V2Zm9 0v6h5M8 12h8M8 16h8"/>',pause:'<path d="M8 5v14M16 5v14"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',exit:'<path d="M10 3H3v18h7m5-15 6 6-6 6M7 12h14"/>'};
 return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.note}</svg>`;
}
export function mark(){return '<svg class="brand-mark" viewBox="0 0 45 45" fill="currentColor" aria-hidden="true"><path d="M2 2h17v17H2zM24 2h17v17H24zM2 24h17v17H2z"/><path d="m30 23 15 8-8 15-15-8z"/></svg>';}
export function symbol(kind,x,y,s=1,color='#d5bd80'){
 const p={
  leaf:'<path d="M-10 10Q-19-14 12-15Q19 10-10 10Z"/><path d="m-11 14 20-26" stroke="#514b30" stroke-width="1.6"/>',
  bird:'<path d="M-20-3Q-6-13 0 1Q6-13 20-3Q8-5 0 10Q-8-5-20-3Z"/>',
  star:'<path d="m0-15 4 10 11 1-8 7 3 12-10-6-10 6 3-12-8-7 11-1Z"/>',
  drop:'<path d="M0-17Q-20 4-9 13Q0 22 9 13Q20 4 0-17Z"/>',
  moon:'<path d="M6-15A16 16 0 1 0 6 15A14 14 0 0 1 6-15Z"/>'
 };
 return `<g transform="translate(${x} ${y}) scale(${s})" fill="${color}">${p[kind]||p.star}</g>`;
}
function wrap(body,bg='#d9c7a0',label='',w=440,h=360){
 const n='a'+(++serial);
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${label}"><defs><radialGradient id="${n}"><stop offset="0" stop-color="#fff" stop-opacity=".10"/><stop offset="1" stop-color="#000" stop-opacity=".23"/></radialGradient><pattern id="${n}p" width="4" height="4" patternUnits="userSpaceOnUse"><path d="M0 0h1v1H0Z" fill="#fff" opacity=".055"/><path d="M2 2h1v1H2Z" fill="#000" opacity=".09"/></pattern></defs><rect width="100%" height="100%" fill="${bg}"/>${body}<rect width="100%" height="100%" fill="url(#${n})" pointer-events="none"/><rect width="100%" height="100%" fill="url(#${n}p)" pointer-events="none"/></svg>`;
}
export function artwork(id,state={},lens=false){
 if(id==='xo')return wrap(`<g stroke="#642e24" stroke-width="9" stroke-linecap="square">${repeat(8,i=>{const x=72+(i%4)*99,y=64+Math.floor(i/4)*73;return `<path d="m${x-13} ${y-13} 26 26m0-26-26 26"/>`;})}</g><path d="M40 203h360" stroke="#2f342a" stroke-width="4"/><g fill="none" stroke="#3b4132" stroke-width="9"><circle cx="155" cy="278" r="26"/><circle cx="285" cy="278" r="26"/></g>`,'#d8c9a5','Eight X symbols above a line, two O symbols below.');
 if(id==='flock')return wrap(`<circle cx="342" cy="70" r="39" fill="#cfb877" opacity=".3"/>${repeat(18,i=>symbol('bird',55+(i%6)*66,48+Math.floor(i/6)*54,.78,'#222c2b'))}<path d="M0 219Q125 195 230 215T440 208" fill="none" stroke="#443f2e" stroke-width="13"/>${repeat(3,i=>`<g transform="translate(${90+i*130} 277)"><path d="M-40-3q40 30 80 0l-8 26q-32 20-64 0Z" fill="#736039"/><ellipse rx="39" ry="12" fill="#322f24" stroke="#9c8353" stroke-width="3"/><path d="m-38 7 70 17m-66-10 62 16m-48 4 45-23" stroke="#b29b68" fill="none" stroke-width="2"/></g>`)}`,'#a5ada0','Eighteen birds above a branch. Three nests below it.');
 if(id==='night')return wrap(`${repeat(12,i=>symbol('star',61+(i%4)*105,50+Math.floor(i/4)*55,.65,'#d8c28d'))}<path d="M0 221h440" stroke="#c6a66a" stroke-width="2"/><path d="M0 226q80 30 150 0t150 0t140 0" fill="none" stroke="#799c9b" opacity=".25"/>${repeat(4,i=>symbol('moon',61+i*105,289,1.3,'#d2ceab'))}`,'#253d45','Twelve stars above a horizon. Four crescent moons below.');
 if(id==='absence')return wrap(`<g transform="translate(220 180) rotate(${(state.rotation||0)*90}) translate(-220 -180)"><path d="m220 10-7 12h14Z" fill="#b08a48"/><rect x="35" y="35" width="370" height="290" rx="2" fill="#282b26"/>${repeat(14,i=>`<rect x="${52+(i%7)*49}" y="${62+Math.floor(i/7)*57}" width="27" height="36" fill="#d8cbaa"/>`)}<path d="M35 202h370" stroke="#d8cbaa" stroke-width="5"/><rect x="110" y="245" width="55" height="40" fill="#d8cbaa"/><rect x="275" y="245" width="55" height="40" fill="#d8cbaa"/></g>`,'#bbae8e','A dark pierced panel. Brass turning studs surround the frame. A small triangle marks its orientation.');
 if(id==='chromatic')return wrap(`${!lens?repeat(17,i=>`<path d="m${37+(i%7)*57} ${39+Math.floor(i/7)*85} 13 22-25-3Z" fill="#b96b4e" opacity=".8"/>`):''}${repeat(10,i=>`<circle cx="${55+(i%5)*82}" cy="${66+Math.floor(i/5)*70}" r="15" fill="#387b94" stroke="#153d51" stroke-width="1"/>`)}<path d="M30 212h380" stroke="#415b64" stroke-width="4"/>${repeat(5,i=>`<circle cx="${55+i*82}" cy="283" r="18" fill="#387b94" stroke="#153d51" stroke-width="1"/>`)}${!lens?repeat(7,i=>`<path d="m${33+i*60} 255 15 25-27-4Z" fill="#b96b4e" opacity=".8"/>`):''}${lens?'<rect width="440" height="360" fill="#45b8f1" opacity=".15"/>':''}`,'#bfc5b6',lens?'Blue inspection view: ten blue disks above, five below.':'Blue disks and rust triangles on a pale ground, separated by a horizontal bar.');
 if(id==='sculpture'){
  const ids=['xo','flock','night','absence','chromatic'];const vals=['4','6','3','7','2'];
  return wrap(`<ellipse cx="220" cy="327" rx="169" ry="13" fill="#0a100f" opacity=".4"/><path d="M54 169 80 151h310l-18 18Z" fill="#c3b18b"/><path d="M54 169h318v22H54Z" fill="#83765b"/>${repeat(5,i=>{const x=65+i*62;return `<path d="M${x} 103l13-13h40l-13 13Z" fill="#c2a86f"/><path d="M${x+40} 103l13-13v61l-13 13Z" fill="#6a5232"/><rect x="${x}" y="103" width="40" height="61" fill="#9b7f4e"/><text x="${x+20}" y="130" fill="#ead7af" text-anchor="middle" font-size="12" font-family="serif">${['I','II','III','IV','V'][i]}</text><text x="${x+20}" y="153" fill="#181e19" text-anchor="middle" font-size="20" font-family="serif">${state.solved?.includes(ids[i])?vals[i]:'·'}</text>`;})}<g fill="none" stroke="#b09356" stroke-width="19"><ellipse cx="148" cy="249" rx="42" ry="54"/><ellipse cx="284" cy="249" rx="42" ry="54"/></g><path d="M74 308h292l20 16H54Z" fill="#b9ad92"/>`,'#24302b','Five numbered brass weights above a slab. Two brass rings support it.');
 }
 if(id==='landing')return wrap('<path d="M0 278q220-28 440 0v82H0Z" fill="#706847"/><ellipse cx="232" cy="296" rx="153" ry="22" fill="#3d4938" opacity=".5"/><path d="M70 280q25-19 70-9l18-17q34 20 54 6l45-8 40 18q50-8 65 17-65 32-154 16-81 6-138-23Z" fill="#a5b16a" stroke="#73834b" stroke-width="3"/><path d="M99 114h242v32l-59 20-18 56h-95l-12-54-43-13-46-4-25-36Z" fill="#313e42"/><path d="M103 112h238v13H103Z" fill="#708384"/><path d="M171 217h96l20 28H150Z" fill="#48565b"/><path d="m105 211-22-25m243 22 23-30m-27 80 34-5" stroke="#dbca99" stroke-width="3"/>','#d5bc8a','A heavy anvil has landed on and flattened a puddle of green goo.');
 if(id==='ship')return wrap('<path d="M0 210q80-25 150 0t150 0t140 0v150H0Z" fill="#395765"/><path d="m277 222 57-119 72 119Z" fill="#d9dfd0"/><path d="m334 103-10 119h82Z" fill="#a7c4c5"/><path d="m277 222 44 100 85-100Z" fill="#799b9e" opacity=".28"/><g transform="rotate(-24 174 209)"><path d="M64 195h224l-45 51H102Z" fill="#343b39"/><path d="M102 168h145v28H102Z" fill="#d4cbab"/><path d="M134 134h25v35h-25Zm48 0h25v35h-25Z" fill="#845f44"/><path d="M100 200h160" stroke="#baa27a" stroke-width="3"/></g><path d="M42 62q5-20 32-13 13-27 43-12 26-12 38 11 30-6 42 18Z" fill="#d9dfd1"/><path d="M208 64q10-20 34-14 14-25 42-10 26-13 42 8 30-5 40 18Z" fill="#d9dfd1"/><text x="219" y="99" text-anchor="middle" fill="#dfe5d5" font-family="Georgia,serif" font-weight="bold" font-size="32" letter-spacing="12">LET US</text><path d="M0 256q70-18 140 0t140 0t160 0M0 290q70-18 140 0t140 0t160 0" fill="none" stroke="#769499" stroke-width="2"/>','#7e9b9f','A boat sinks beside an iceberg in icy water. LET US is written in the clouds.');
 if(id==='burial')return wrap('<circle cx="320" cy="62" r="32" fill="#c8c3a5"/><path d="M0 259q110-75 220-26t220 26v101H0Z" fill="#384139"/><path d="m220 265 94-29 65 34-91 40Z" fill="#181f1c"/><path d="m220 265 10 29 58 38v-22Z" fill="#64614b"/><path d="M246 147q0-44 40-44t40 44v81h-80Z" fill="#999f8b"/><path d="M278 124v65m-17-46h34" stroke="#5e6a61" stroke-width="5"/><path d="m168 156-21 111" stroke="#b9a27c" stroke-width="7"/><path d="m133 256 30 5-10 35-25-5Z" fill="#79857a"/><rect x="61" y="219" width="64" height="66" rx="5" fill="#141d1c"/><ellipse cx="93" cy="219" rx="32" ry="9" fill="#080f10" stroke="#aab3a5" stroke-width="2"/><path d="M62 230q-31-49 27-59" fill="none" stroke="#bbc4b8" stroke-width="3"/><text x="92" y="261" text-anchor="middle" fill="#d9d5bd" font-size="12" font-family="serif">BLACK</text>','#66766f','A can of black paint stands beside a fresh burial and a shovel.');
 if(id==='factory')return wrap('<path d="M0 289h440v71H0Z" fill="#6c7460"/><path d="M66 281h309v18H66Z" fill="#53604f"/><path d="M184 265c-101 0-82-126-30-187 17-20 40-21 59 4 51 68 74 183-29 183Z" fill="#ddd4b5"/><path d="M227 147h102v120H227Z" fill="#a89b79"/><path d="M259 82h27v70h-27Zm47 16h24v55h-24Z" fill="#7e7f69"/><path d="M271 80q-31-17-6-35 42-16 36-43" fill="none" stroke="#c2c6ae" stroke-width="16" opacity=".7"/><path d="M316 94q-18-27 8-41" fill="none" stroke="#c2c6ae" stroke-width="12" opacity=".7"/><path d="M152 172h17v22h-17Zm44 0h17v22h-17Zm58 12h18v23h-18Zm40 0h18v23h-18Z" fill="#6e7966"/><path d="M171 223h27v43h-27Z" fill="#798372"/><path d="M199 267h143" stroke="#404b40" stroke-width="5"/>','#b8bea1','An egg-shaped industrial factory with windows, chimneys, and smoke.');
 return wrap('');
}
export function mural(side){
 const values=side==='left'?MURAL_LEFT:MURAL_RIGHT;
 return wrap(`<path d="M18 265h1260" stroke="#b49358" stroke-width="3"/><path d="M32 24h100m-10-7 10 7-10 7" stroke="#b49358" fill="none" stroke-width="2"/>${values.map(([kind,count],i)=>`<g>${repeat(count,j=>symbol(kind,65+i*256+(j%4)*45,64+Math.floor(j/4)*38,.6,'#d2c291'))}<path d="M${(i+1)*256} 40v208" stroke="#796644" stroke-width="1" opacity=".55"/>${symbol(kind,126+i*256,298,.7,'#a28e62')}</g>`).join('')}`,'#29352f',side==='left'?'Left mural, with an arrow reading left to right. Five panels of leaves, birds, stars, drops and moons.':'Right mural. Five panels of moons, leaves, drops, stars and birds.',1280,330);
}
export function foodIcon(name){
 let fill='#87a16b',body='<path d="M6 23Q4 5 20 6Q36 4 35 23Q30 39 20 37Q6 37 6 23Z"/>';
 if(['Pear','Plum','Lemon','Cherry','Banana','Orange','Fig','Grape','Blackberry','Apple','Tomato'].includes(name)){
  fill=({Pear:'#aea653',Plum:'#967a9c',Lemon:'#c9b95d',Cherry:'#c57568',Banana:'#d1bd70',Orange:'#c59c62',Fig:'#b58d9c',Grape:'#a397bb',Blackberry:'#737080',Apple:'#c8937f',Tomato:'#c78364'})[name];
  body=name==='Banana'?'<path d="M5 10q18 23 29-4 7 31-16 32Q2 36 5 10Z"/>':name==='Blackberry'||name==='Grape'?repeat(9,i=>`<circle cx="${12+(i%3)*8}" cy="${13+Math.floor(i/3)*8}" r="6"/>`):'<path d="M7 24C0 7 14 6 20 12 29 4 42 12 33 29 26 43 21 36 19 36 11 40 8 30 7 24Z"/>';
 }else if(name==='Squash'){fill='#d0b270';body='<path d="M14 3q17-4 15 14l-1 5q13 19-9 18Q-2 40 11 21l3-6Z"/>';
 }else if(name==='Eggplant'){fill='#9e85ad';body='<path d="M28 8Q46 29 19 38 0 42 9 27 24 25 20 13Z"/><path d="m20 11 1-9 7 6 7-1-5 9Z" fill="#9eae73"/>';
 }else if(name==='Egg'){fill='#d7ccb4';body='<path d="M20 3C5 9-2 37 20 39 42 37 35 9 20 3Z"/>';
 }else if(['Carrot','Chili','Pepper','Corn'].includes(name)){fill='#c1a06d';body='<path d="M12 7q27-2 19 13L7 39Z"/>';
 }else if(name==='Mushroom'){fill='#cab69b';body='<path d="M17 20h9v19h-9Z"/><path d="M3 22Q20-15 39 22Z"/>';
 }else{body='<path d="M20 38C-5 33 1 5 16 10 14-4 36 3 33 14 48 18 35 36 20 38Z"/><path d="m20 34 2-23m-2 17-10-8m11 3 10-7" fill="none" stroke="#405b39" stroke-width="1.3"/>';}
 return `<svg viewBox="0 0 44 44" aria-hidden="true"><g fill="${fill}" stroke="#d7ceab" stroke-opacity=".2" stroke-width=".6">${body}</g></svg>`;
}
